(function(){
  'use strict';
  const D=window.ITIHASA_BOOKS=window.ITIHASA_BOOKS||{};
  const base='/vivekadrishti/articles/scripture/mahabharata/';
  const bori={title:'Bhandarkar Oriental Research Institute — Mahābhārata critical edition project',url:'https://bori.ac.in/department/mahabharata/',detail:'Institutional account of the critical-edition project and its manuscript basis.'};
  const common=[
    bori,
    {title:'V. S. Sukthankar, Prolegomena to the Ādiparvan',detail:'Foundational statement of the critical edition’s genealogical method and limits.'},
    {title:'J. A. B. van Buitenen, The Mahābhārata, 3 vols.',detail:'Annotated translation of Books 1–5 with extensive introductions (University of Chicago Press, 1973–1978).'},
    {title:'Bibek Debroy, The Mahabharata, 10 vols.',detail:'English translation keyed to the BORI critical edition (Penguin, 2010–2014).'},
    {title:'Alf Hiltebeitel, Rethinking the Mahābhārata',detail:'Study of composition, design and religious argument (University of Chicago Press, 2001).'}
  ];
  const unit=(title,range,...paragraphs)=>({title,range,paragraphs});
  const theme=(title,...paragraphs)=>({title,paragraphs});

  function make(slug,o){
    const n=o.number;
    D[`mahabharata/${slug}`]={
      work:'Mahābhārata', title:o.title, devanagari:o.devanagari,
      position:o.position||`Book ${n} of the eighteen-parva Mahābhārata`, meaning:o.meaning,
      traditionalExtent:o.traditional, criticalExtent:o.critical,
      setting:o.setting||'Kuru north India and the epic’s wider sacred geography',
      textualBasis:'BORI constituted text, checked against commonly printed vulgate divisions',
      description:o.description||`${o.title}: structure, chapter-by-chapter contents, textual history, interpretation and reception.`,
      lead:o.lead,
      history:[
        `The ${o.title} is not an independently dated composition. It belongs to the layered growth of the Mahābhārata, whose narrative, didactic and theological materials took shape over centuries in oral performance and manuscript transmission; arguments about date must therefore address individual passages and strata, not assign the entire book to one year.`,
        ...(o.history||[])
      ],
      structure:[
        `The commonly printed or “vulgate” arrangement gives this book ${o.traditional}. The BORI critical edition gives ${o.critical}; the difference reflects the removal, relocation or recombination of passages that lacked sufficient support across the manuscript traditions, not a claim that excluded readings are culturally unimportant.`,
        ...(o.structure||[])
      ],
      numberingNote:o.numberingNote||'The ranges below follow the traditional chapter numbering used in many public-domain translations. Critical-edition chapter numbers are different where the constituted text is shorter.',
      contentsIntro:o.contentsIntro||[`The following map follows the internal upa-parvas and major narrative units rather than reducing the book to a single plot paragraph. Each entry identifies what changes in the story and why that unit matters to the architecture of the epic.`],
      units:o.units,
      interpretation:o.interpretation,
      reception:[
        ...(o.reception||[]),
        `The ${o.title} has circulated through Sanskrit commentary, vernacular retelling, theatre, recitation and modern translation. Reception frequently isolates its strongest episodes from their book-level setting, so this article keeps later fame distinct from the passage’s role in the received epic.`
      ],
      textualHistory:[
        `The BORI editors constituted the ${o.title} by comparing manuscripts from northern and southern recensional families and recording rejected and variant readings in the critical apparatus. The result is a reconstruction of a common transmissional ancestor, not Vyāsa’s autograph and not a complete replacement for regional texts.`,
        ...(o.textualHistory||[])
      ],
      sources:[...common,
        ...(Number.isFinite(Number(n)) ? [{title:`K. M. Ganguli translation — Mahābhārata Book ${n}`,url:`https://sacred-texts.com/hin/m${String(n).padStart(2,'0')}/index.htm`,detail:'Public-domain translation of a commonly printed Sanskrit text; chapter numbering is useful but does not equal the BORI edition.'}] : []),
        {title:`${o.title} — public structure cross-check`,url:o.wiki,detail:'Used for navigation and traditional chapter ranges; historical claims are controlled by the critical-edition and scholarly works above.'},
        ...(o.sources||[])
      ]
    };
  }

  make('adi-parva',{
    number:1,title:'Ādi Parva',devanagari:'आदिपर्व',meaning:'Book of the Beginning',traditional:'19 upa-parvas and 236 chapters',critical:'19 upa-parvas, 225 chapters and about 7,200 ślokas',wiki:'https://en.wikipedia.org/wiki/Adi_Parva',
    lead:[
      'The Ādi Parva builds the entire causal world of the Mahābhārata. It establishes the poem’s nested performances, the snake-sacrifice frame, the lunar and Kuru genealogies, Bhīṣma’s vow, the extraordinary births of the rival cousins, their education and first attempts to destroy one another.',
      'Its final third carries the Pāṇḍavas from the lac-house escape through Draupadī’s marriage and the creation of Indraprastha to Arjuna’s exile, Subhadrā’s abduction and the burning of the Khāṇḍava forest. These are not detachable adventures: they create the kinship, debts, alliances and territorial claims that make the later dice game and war possible.'
    ],
    history:['The opening book is especially composite. Bhr̥gu legends, snake lore, dynastic genealogy, royal foundation narratives and the Khāṇḍava cycle preserve materials with distinct affiliations; the recitation frames also repeatedly explain how a vast inherited work can contain many genres.'],
    structure:['Its nineteen named upa-parvas are unusually fine-grained. The first five establish frame and mythic prehistory; the long Sambhava carries the dynastic line into the Pāṇḍavas’ youth; the remaining books narrate survival, marriage, kingship and the acquisition of a new political centre.'],
    units:[
      unit('Anukramaṇikā Parva','chapter 1','Ugraśravas Sauti arrives at the Naimiṣa forest sacrifice and announces the Bhārata he heard from Vaiśaṃpāyana. The chapter praises the poem’s comprehensiveness, supplies an initial table of contents and places all later narration inside a chain of remembered performances.'),
      unit('Saṃgraha Parva','chapter 2','A fuller survey enumerates parvas, sub-parvas and major events, while giving traditional measures of the epic’s extent. Its catalogues are textual self-description: they show how transmitters conceptualized the whole, although different manuscripts do not preserve every total identically.'),
      unit('Pauṣya Parva','chapter 3','The story of Uttaṅka, his teacher’s household and the serpent king Takṣaka connects brahmanical obligation, gifts and vengeance to Janamejaya’s future snake sacrifice. The episode also introduces the volatile relation between royal power and ritual specialists that governs the outer frame.'),
      unit('Pauloma Parva','chapters 4–12','Bhr̥gu-line narratives recount Pulomā’s abduction, Cyavana’s birth, Ruru’s love for Pramadvarā and the origin of Ruru’s hatred of snakes. These genealogical tales prepare the serpent theme while distinguishing poisonous aggressors from harmless snakes, complicating indiscriminate extermination.'),
      unit('Āstīka Parva','chapters 13–58','Kadru and Vinatā, the wager over Uccaiḥśravas, Garuḍa’s quest for amr̥ta and the curse upon Kadru’s serpent sons supply the cosmic prehistory of the sacrifice. When Janamejaya’s rite begins drawing snakes into the fire, the young sage Āstīka wins a boon and stops it, converting a revenge ritual into an argument about restraint, kinship and survival.'),
      unit('Aṃśāvataraṇa Parva','chapters 59–64','The narrative lists divine and anti-divine beings who descend into human lineages as the burdened earth appeals for relief. This avatāra catalogue overlays the dynastic story with a cosmic explanation, but it does not erase the human choices through which catastrophe develops.'),
      unit('Sambhava Parva','chapters 65–142','The longest opening unit moves from Duḥṣanta and Śakuntalā, Yayāti and the Pūru line to Śāntanu, Gaṅgā, Bhīṣma and Satyavatī. It then narrates the births of Dhr̥tarāṣṭra, Pāṇḍu and Vidura; Pāṇḍu’s curse; the births of the Kauravas and Pāṇḍavas; education under Droṇa; Ekalavya; the tournament; Karṇa’s appearance; and the capture of Drupada. Dynastic continuity is repeatedly purchased through vows, substitutions and extraordinary reproduction, making succession structurally unstable before the princes can act.'),
      unit('Jatugr̥ha-dāha Parva','chapters 143–153','Duryodhana’s faction sends the Pāṇḍavas to Vāraṇāvata and constructs a palace of lacquer and other combustibles. Warned by Vidura, they prepare a tunnel and escape when the building burns; public belief in their deaths frees them temporarily from court surveillance but inaugurates a life of disguise and counter-deception.'),
      unit('Hiḍimba-vadha Parva','chapters 154–158','In the forest Bhīma kills the rākṣasa Hiḍimba and marries his sister Hiḍimbā for a limited time. Their son Ghaṭotkaca belongs simultaneously to forest and Kuru worlds and later becomes a decisive night warrior, so this short episode plants a major military alliance.'),
      unit('Baka-vadha Parva','chapters 159–166','Living incognito at Ekacakrā, the brothers learn that the town must supply food and a human victim to the rākṣasa Baka. Kuntī sends Bhīma, who eats the provisions and kills Baka; heroic protection is presented through a brahman household’s fear and the ethics of repaying hospitality.'),
      unit('Caitraratha Parva','chapters 167–185','Arjuna defeats the gandharva Citraratha, gains knowledge and learns the importance of appointing a priest. The unit includes lineage and sacred narratives, then directs the brothers toward Draupadī’s svayaṃvara with Dhaumya as their purohita.'),
      unit('Svayaṃvara Parva','chapters 186–194','At Drupada’s court Arjuna, disguised as a brahman, completes the archery test and wins Draupadī while Bhīma contains the defeated kings. The event restores the Pāṇḍavas to high politics and joins them to a kingdom created in part by Drupada’s conflict with Droṇa.'),
      unit('Vaivāhika Parva','chapters 195–201','Kuntī’s inadvertent command to share what has been brought home becomes the starting point for debate over Draupadī’s marriage to all five brothers. Vyāsa supplies precedents and a divine prehistory; the final arrangement regulates access and makes Draupadī the common dynastic centre of the brothers.'),
      unit('Vidurāgamana Parva','chapters 202–209','Once the Pāṇḍavas’ survival and alliance are known, Vidura travels on Dhr̥tarāṣṭra’s behalf to bring them and Draupadī back. Courtly reconciliation is real but limited: the settlement responds to changed power rather than resolving the rivalry.'),
      unit('Rājyalābha Parva','chapters 210–214','The kingdom is divided and the Pāṇḍavas receive Khāṇḍavaprastha, which they transform into Indraprastha. Nārada’s visit and the story of Sunda and Upasunda lead to a rule governing the brothers’ relations with Draupadī, linking domestic order to political stability.'),
      unit('Arjuna-vanavāsa Parva','chapters 215–220','Arjuna violates the brothers’ access rule while retrieving weapons to assist a petitioner and voluntarily enters exile. His travels and marriages to Ulūpī and Citrāṅgadā broaden the Pāṇḍavas’ kinship network beyond the Kuru-Pañcāla centre.'),
      unit('Subhadrā-haraṇa Parva','chapters 221–222','With Kr̥ṣṇa’s counsel, Arjuna carries away Subhadrā and later regularizes the marriage with the Yādavas. The episode produces Abhimanyu and turns the Vṛṣṇi alliance into close kinship, crucial both to the war and to postwar succession.'),
      unit('Haraṇāharaṇa Parva','chapter 223','Subhadrā is received at Indraprastha and reconciled with Draupadī; the births of Draupadī’s five sons and of Abhimanyu complete the new generation. The compact chapter converts potentially rival marriages into a working, if delicate, household settlement.'),
      unit('Khāṇḍava-dāha Parva','chapters 224–236','Agni asks Kr̥ṣṇa and Arjuna to help consume the Khāṇḍava forest despite Indra’s resistance. Their slaughter of escaping beings is rewarded with weapons, chariot and lasting alliance; Maya is spared and will build the hall of the next book. The episode is triumphal, violent and cosmological at once, and later consequences—including the survival of Aśvasena—prevent it from functioning as uncomplicated heroic conquest.')
    ],
    interpretation:[
      theme('Genealogy as political argument','Genealogy does more than introduce characters. Competing claims depend on birth order, bodily qualification, niyoga, divine paternity, adoption, vow and marriage; the book repeatedly shows that “legitimate succession” has already been constructed through exceptions.'),
      theme('Frames, memory and encyclopaedism','The poem presents itself through Sauti, Vaiśaṃpāyana and the snake-sacrifice audience. This architecture authorizes digression and disagreement: knowledge arrives as remembered speech embedded inside later ritual and political situations.'),
      theme('Heroism and moral cost','Bhīma’s protection of Ekacakrā and Arjuna’s victory at the svayaṃvara sit beside Ekalavya’s thumb, the lac-house counterplot and the Khāṇḍava massacre. The first book therefore refuses to reserve ethical ambiguity for the final war.')
    ],
    reception:['Śakuntalā, Ekalavya, Draupadī’s marriage and the Khāṇḍava fire became major sites of later literary and political reinterpretation. Kālidāsa’s Śakuntalā is not a simple reproduction of the epic episode, and modern retellings frequently recenter figures whom the dynastic narrative marginalizes.']
  });

  make('sabha-parva',{
    number:2,title:'Sabhā Parva',devanagari:'सभापर्व',meaning:'Book of the Assembly Hall',traditional:'10 upa-parvas and 81 chapters',critical:'9 upa-parvas and 72 chapters',wiki:'https://en.wikipedia.org/wiki/Sabha_Parva',
    lead:['The Sabhā Parva turns the Pāṇḍavas’ new capital into the stage of both imperial achievement and dispossession. Maya’s extraordinary hall, the rājasūya, Jarāsandha’s death and the defeat of rival kings culminate in a sovereignty whose splendour intensifies Duryodhana’s resentment.','The dice match then reverses every gain. Yudhiṣṭhira stakes wealth, kingdom, brothers, himself and Draupadī; her questions about enslavement and legal authority expose the assembly’s inability to defend its own norms, and a second game fixes the exile that governs Books 3 and 4.'],
    history:['The book tightly joins court epic and ritual-political reflection. Its conquest lists, hall catalogues, royal-sacrifice materials and legal debate need not share one compositional history, even though the received book arranges them as a single rise-and-fall movement.'],
    units:[
      unit('Sabhākriyā Parva','chapters 1–4','Maya constructs a hall whose surfaces, doors and pools defeat ordinary perception. Nārada visits and describes ideal and divine assemblies; the built environment advertises Pāṇḍava power but also becomes the setting for Duryodhana’s humiliation.'),
      unit('Lokapāla-sabhākhyāna Parva','chapters 5–13','Nārada surveys the halls of Yama, Varuṇa, Indra, Kubera and Brahmā and questions Yudhiṣṭhira about royal administration. The comparison places earthly kingship under cosmic models while the memory of Pāṇḍu turns the rājasūya into a filial and dynastic duty.'),
      unit('Rājasūyārambha Parva','chapters 14–19','Counsellors agree that Jarāsandha must be defeated before imperial consecration can proceed, because he holds kings captive for sacrifice. Kr̥ṣṇa explains the political danger and leads Bhīma and Arjuna to Magadha in disguise.'),
      unit('Jarāsandha-vadha Parva','chapters 20–24','Jarāsandha accepts Bhīma’s challenge and the two wrestle for days. At Kr̥ṣṇa’s signal Bhīma tears him apart in the manner implied by his divided birth, frees the captive kings and installs Sahadeva of Magadha.'),
      unit('Digvijaya Parva','chapters 25–31','The four Pāṇḍava brothers campaign in the cardinal directions, collecting tribute and recognition. The geographical catalogues project imperial reach; they are literary-political maps and cannot simply be read as records of a single historical campaign.'),
      unit('Rājasūyika Parva','chapters 32–34','Preparations gather kings, priests, wealth and ritual specialists at Indraprastha. The sacrifice distributes honour as well as gifts, making protocol a test of the political order created by conquest.'),
      unit('Arghyāharaṇa Parva','chapters 35–38','Bhīṣma argues that Kr̥ṣṇa deserves the first worship. Śiśupāla contests the choice, attacks Kr̥ṣṇa’s status and reopens older disputes about lineage and conduct, revealing that ceremonial precedence cannot be separated from factional history.'),
      unit('Śiśupāla-vadha Parva','chapters 39–44','Śiśupāla exceeds the offences Kr̥ṣṇa had promised to forgive and is killed by the discus. The narrative identifies his antagonism with earlier anti-divine births and absorbs his released radiance into Kr̥ṣṇa, joining royal violence to Vaiṣṇava theology.'),
      unit('Dyūta Parva','chapters 45–73','Duryodhana’s envy and Śakuni’s skill produce the invitation to dice; Dhr̥tarāṣṭra permits what Vidura condemns. Yudhiṣṭhira loses each stake, and Duḥśāsana drags Draupadī into the hall. She asks whether a man who has already lost himself can stake his wife, but the elders evade judgment; vows of vengeance replace the failed law until Dhr̥tarāṣṭra grants restitution.'),
      unit('Anudyūta Parva','chapters 74–81','A second match is imposed despite the first settlement. The losing condition—twelve years in the forest and one year concealed—turns manipulation into a formally ratified political outcome; the departing Pāṇḍavas and Draupadī embody vows that will govern the war.')
    ],
    interpretation:[theme('The assembly and failed institutions','The sabhā is at once an architectural marvel, political council, ritual theatre and gambling room. Its failure is institutional: senior men possess knowledge but cannot translate it into protection when the ruler, heir, invited player and legal categories have been compromised.'),theme('Sovereignty, spectacle and envy','The rājasūya creates universalizing sovereignty through conquest, tribute, precedence and largesse. The dice game uses the same courtly mechanisms—invitation, witness, gift and stake—to dismantle it, showing how fragile spectacular power remains.')],
    reception:['Draupadī’s interrogation of the assembly is among the epic’s most extensively debated legal and ethical scenes. Performance traditions differ sharply over the attempted disrobing and divine intervention, making the distinction between critical text, regional recension and later devotional retelling especially important.']
  });

  make('vana-parva',{
    number:3,title:'Vana Parva',devanagari:'वनपर्व',meaning:'Book of the Forest',traditional:'21 upa-parvas and 324 chapters',critical:'16 upa-parvas and 299 chapters',wiki:'https://en.wikipedia.org/wiki/Vana_Parva',
    lead:['The Vana Parva narrates the Pāṇḍavas’ twelve-year forest exile, but exile is only its organizing frame. Pilgrimage catalogues, ascetic encounters, philosophical debates and long embedded tales turn the forest into an alternative archive of kingship, suffering, fidelity and liberation.','Arjuna travels to acquire divine weapons while Yudhiṣṭhira repeatedly hears stories that mirror dispossession: Nala loses a kingdom through dice, Sāvitrī confronts death, Rāma undergoes exile, and many rulers discover that dharma cannot be measured by immediate success.'],
    history:['The great length and anthology-like character of Vana make its stratification especially visible. Pilgrimage māhātmyas, weapon narratives, didactic dialogues and famous independent tales circulated through traditions larger than this book and were reshaped by their placement within the exile.'],
    units:[
      unit('Āraṇyaka Parva','chapters 1–10','The exiles leave the city with brahmans and establish themselves near the Kāmyaka and Dvaita forests. The solar food vessel solves the problem of sustaining dependants, while Vidura, Dhr̥tarāṣṭra and Kr̥ṣṇa debate responsibility for the catastrophe.'),
      unit('Kirmīra-vadha Parva','chapter 11','Bhīma kills Kirmīra, brother of Baka and ally of Hiḍimba. The short encounter links the new exile to earlier forest violence and restores the protector role Bhīma performed at Ekacakrā.'),
      unit('Arjunābhigamana Parva','chapters 12–37','Allies visit the Pāṇḍavas and Draupadī and Bhīma press Yudhiṣṭhira about anger, patience and kingship. Vyāsa directs Arjuna toward divine weapons; the debates clarify that the brothers accept exile without agreeing on how forbearance relates to justice.'),
      unit('Kirāta Parva','chapters 38–41','Arjuna’s austerities culminate in combat with a hunter who is Śiva in disguise. Recognition after apparent defeat wins the Pāśupata weapon; martial excellence becomes dependent on ascetic discipline and submission to a divine opponent.'),
      unit('Indralokāgamana Parva','chapters 42–51','Arjuna travels to Indra’s heaven, learns celestial warfare and music, and receives weapons. Urvaśī’s curse that he become a eunuch is transformed into a future advantage during the incognito year, linking heavenly encounter to Book 4.'),
      unit('Nalopākhyāna Parva','chapters 52–79','Br̥hadaśva tells of Nala and Damayantī: svayaṃvara, divine rivalry, dice-driven loss, separation, disguise, acquired knowledge and reunion. The tale consoles Yudhiṣṭhira but also teaches practical mastery of dice, turning narrative analogy into preparation for recovered rule.'),
      unit('Tīrthayātrā Parva','chapters 80–157','Lomaśa guides a vast pilgrimage while sacred places call forth local myths, royal genealogies and ritual claims. The journey maps Bhārata through remembered story; it also reunites the brothers with Arjuna after his acquisition of weapons.'),
      unit('Yakṣa-yuddha Parva','chapters 158–164','In Himalayan regions Bhīma clashes with yakṣas and Kubera’s forces while Draupadī seeks fragrant lotuses. The episode tests heroic impatience against Yudhiṣṭhira’s restraint and ends with accommodation rather than conquest.'),
      unit('Nivātakavaca-yuddha Parva','chapters 165–175','Arjuna recounts his campaigns against the Nivātakavacas and Kālakeyas using divine weapons. The narrative displays the terrible scale of the arsenal being prepared for Kurukṣetra while locating it first in a cosmic war authorized by the gods.'),
      unit('Ajagara Parva','chapters 176–181','A great serpent seizes Bhīma and is revealed as the cursed king Nahuṣa. Yudhiṣṭhira answers questions about brahmanhood and conduct, and knowledge releases both captor and captive; social status is debated through qualities rather than mere designation.'),
      unit('Mārkaṇḍeya-samāsyā Parva','chapters 182–231','Mārkaṇḍeya narrates creation, flood, exemplary rulers, faithful spouses and the child-like cosmic Nārāyaṇa. Within this large dossier, the Sāvitrī story makes a woman’s disciplined speech and fidelity capable of winning back her husband from Yama.'),
      unit('Draupadī–Satyabhāmā Saṃvāda','chapters 232–234','Satyabhāmā asks whether charms or control explain Draupadī’s relation to her husbands. Draupadī rejects manipulation and presents an exacting account of household labour, discipline and reciprocal duty, a normative speech framed by the extraordinary conditions of her marriage.'),
      unit('Ghoṣa-yātrā Parva','chapters 235–256','Duryodhana visits the cattle stations near the exiles in order to display prosperity, but gandharvas capture him. The Pāṇḍavas rescue their enemy because family honour and royal obligation exceed immediate vengeance; Duryodhana experiences the rescue as humiliation.'),
      unit('Mr̥ga-svapnodbhava Parva','chapter 257','Deer appear in Yudhiṣṭhira’s dream and plead that overhunting is destroying them. The brothers move their camp, a brief ecological correction that marks the material pressure even righteous exiles place on a forest.'),
      unit('Vrīhidrauṇika Parva','chapters 258–260','The story of Mudgala contrasts laboriously gathered grain, hospitality and heavenly reward. Mudgala ultimately refuses impermanent heaven in favour of liberation, shifting the book from endurance toward a critique of reward itself.'),
      unit('Draupadī-haraṇa Parva','chapters 261–270','Jayadratha abducts Draupadī while the brothers are away. They pursue and defeat him; Draupadī demands punishment, but Yudhiṣṭhira’s kinship considerations limit the sentence, allowing a humiliated enemy to survive into the war.'),
      unit('Jayadratha-vimokṣaṇa Parva','chapter 271','Jayadratha undertakes austerities and receives from Śiva the limited power to hold back the Pāṇḍavas when Arjuna is absent. The bridge to Abhimanyu’s death shows how mercy, humiliation, tapas and delayed revenge interact across books.'),
      unit('Rāmopākhyāna Parva','chapters 272–291','Mārkaṇḍeya retells Rāma’s exile, Sītā’s abduction and the war in Laṅkā. As an epic within the epic, the account offers Yudhiṣṭhira a precedent for royal loss and recovery while preserving a Mahābhārata-stage Rāma tradition distinct from the full Vālmīki poem.'),
      unit('Pativratā-māhātmya Parva','chapters 292–298','The chaste wife and the dharma-knowing butcher instruct an irascible brahman that ascetic power does not excuse anger. Household service, occupational duty and non-injury displace spectacular tapas as the test of moral knowledge.'),
      unit('Kuṇḍalāharaṇa Parva','chapters 299–309','Indra approaches Karṇa in disguise and requests his inborn armour and earrings. Karṇa gives them despite warning and receives the one-use spear; generosity, reputation, divine strategy and self-endangerment are fused in the weapon that will later kill Ghaṭotkaca.'),
      unit('Āraṇeya Parva','chapters 310–324','A deer carries away a brahman’s fire sticks, and pursuit brings the brothers to a fatal lake. A yakṣa questions Yudhiṣṭhira after the others fall; his answers and his choice to revive Nakula preserve both maternal lines. The book closes with intellectual and ethical fitness for the incognito year, not a military victory.')
    ],
    interpretation:[theme('Exile as an encyclopaedic frame','The forest removes the protagonists from court but brings the epic into contact with pilgrimage specialists, ascetics, gods, local myths and other royal stories. Apparent digression is the book’s method for comparing the Pāṇḍavas’ crisis with a larger repertoire of loss and recovery.'),theme('Narrative as counsel','Nala, Sāvitrī, Rāma and Mudgala are not inserted merely for entertainment. Each tale answers an immediate problem—dice, death, exile, reward—without collapsing the Pāṇḍavas’ situation into a single moral formula.'),theme('Weapons and restraint','Arjuna amasses world-destroying weapons while Yudhiṣṭhira is trained through questions, pilgrimage and delayed retaliation. The pairing makes capacity and restraint equally necessary, even though the later war will expose their limits.')],
    reception:['Nala–Damayantī, Sāvitrī, the Yakṣa questions and the Rāmopākhyāna have long independent reception histories in literature, performance and education. Their extraction from Vana should not conceal the carefully staged relation between each embedded story and the exiles who hear it.']
  });

  make('virata-parva',{
    number:4,title:'Virāṭa Parva',devanagari:'विराटपर्व',meaning:'Book of Virāṭa',traditional:'4 upa-parvas and 72 chapters',critical:'4 upa-parvas and 67 chapters',wiki:'https://en.wikipedia.org/wiki/Virata_Parva',
    lead:['The Virāṭa Parva narrates the thirteenth year, when discovery would renew the Pāṇḍavas’ exile. Each assumes a court identity at Matsya: Yudhiṣṭhira becomes a gaming companion, Bhīma a cook and wrestler, Arjuna the dance teacher Br̥hannalā, Nakula and Sahadeva animal keepers, and Draupadī the maid Sairandhrī.','The year tests whether royal and martial identities can survive concealment. Kīcaka’s harassment makes Draupadī’s vulnerability the price of secrecy; the final cattle raids permit Arjuna to recover his weapons and reveal the alliance precisely when the calendrical term has expired.'],
    units:[
      unit('Pāṇḍava-praveśa Parva','chapters 1–13','The brothers hide their weapons in a śamī tree, choose names and occupations, and enter Virāṭa’s service. The disguises adapt genuine skills while reversing status: king becomes dependent, warrior performs femininity, and queen serves another queen.'),
      unit('Kīcaka-vadha Parva','chapters 14–24','Commander Kīcaka pursues and publicly assaults Draupadī despite her appeals. Because open intervention would expose the brothers, she arranges a night meeting where Bhīma kills him; his relatives then attempt to burn her with the corpse and are also slain.'),
      unit('Go-haraṇa Parva','chapters 25–69','Trigarta and Kuru forces raid Matsya’s cattle on two fronts. Bhīma rescues Virāṭa in the south, while Arjuna—still dressed as Br̥hannalā—retrieves Gāṇḍīva, reveals himself to prince Uttara and defeats the Kuru heroes without killing them. Dispute over the lunar calendar establishes that the incognito term is complete.'),
      unit('Vaivāhika Parva','chapters 70–72','The Pāṇḍavas disclose their identities at court. Virāṭa offers Uttarā to Arjuna, but he accepts her as a daughter-in-law for Abhimanyu, transforming the refuge relationship into a marriage alliance that will survive the war through Parīkṣit.')
    ],
    interpretation:[theme('Disguise and embodied identity','The book treats identity as performed through speech, clothing, skill and social recognition. Arjuna’s Br̥hannalā role is neither a disposable joke nor a modern identity category; it fulfils Urvaśī’s curse and makes gendered performance central to the recovery of martial selfhood.'),theme('Draupadī and the cost of secrecy','Draupadī must negotiate danger with limited public protection. Her planning with Bhīma exposes the conflict between the collective strategic need to remain hidden and the immediate obligation to answer sexual violence.')],
    reception:['Kīcaka’s death and Br̥hannalā’s revelation are major theatre, dance and painting subjects. Regional performances often expand Draupadī’s courtroom speech and Arjuna’s gendered disguise beyond the scale of the Sanskrit book.']
  });

  make('udyoga-parva',{
    number:5,title:'Udyoga Parva',devanagari:'उद्योगपर्व',meaning:'Book of Effort or Preparations',traditional:'10 upa-parvas and 199 chapters',critical:'12 sections and 197 chapters',wiki:'https://en.wikipedia.org/wiki/Udyoga_Parva',
    lead:['The Udyoga Parva is the epic’s sustained inquiry into whether war can still be prevented. Armies and alliances assemble while priests, kings, Sañjaya and finally Kr̥ṣṇa carry proposals between the camps; each mission narrows the terms without overcoming Duryodhana’s refusal.','Embedded counsel—the Viduranīti, Sanatsujātīya and debates around Kr̥ṣṇa’s embassy—asks what kings owe to kin, subjects and truth. By the time commanders and warriors are ranked, war appears neither accidental nor morally simple: it is the result of decisions repeatedly made in the presence of alternatives.'],
    units:[
      unit('Sainyodyoga Parva','chapters 1–19','The Matsya marriage assembly becomes a council over restitution and strategy. Both sides seek allies; Arjuna chooses unarmed Kr̥ṣṇa while Duryodhana receives the Nārāyaṇī troops, a famous contrast between personal guidance and military quantity.'),
      unit('Sañjaya-yāna Parva','chapters 20–32','Dhr̥tarāṣṭra sends Sañjaya to the Pāṇḍavas with language of peace but no adequate territorial offer. Yudhiṣṭhira states his willingness to accept a reduced settlement, while Kr̥ṣṇa identifies Duryodhana’s dispossession as the obstacle.'),
      unit('Prajāgara Parva','chapters 33–40','Unable to sleep after Sañjaya’s return, Dhr̥tarāṣṭra asks Vidura for counsel. The Viduranīti treats self-control, trustworthy advisers, greed, speech and royal prudence; its very clarity emphasizes the king’s long failure to act on what he knows.'),
      unit('Sanatsujāta Parva','chapters 41–46','Sanatsujāta answers Dhr̥tarāṣṭra on death, ignorance, Vedic learning and brahman. The philosophical dialogue interrupts immediate diplomacy to diagnose delusion at a deeper level: ritual or information without disciplined knowledge cannot save the ruler.'),
      unit('Yānasandhi Parva','chapters 47–73','Sañjaya reports the Pāṇḍava position and the court debates strength, justice and fear. Duryodhana remains confident in his alliances, while elders describe the danger of opposing Kr̥ṣṇa and Arjuna.'),
      unit('Bhagavad-yāna Parva','chapters 74–150','Kr̥ṣṇa undertakes the final embassy, meets Kuntī and addresses the Kuru court. His proposal fails; a plot to seize him prompts revelation of a cosmic form. He then tells Karṇa the secret of his birth and offers him kingship, but Karṇa refuses to abandon Duryodhana while acknowledging the likely outcome.'),
      unit('Sainya-niryāṇa Parva','chapters 151–159','The Pāṇḍavas march to Kurukṣetra and organize their forces under Dhr̥ṣṭadyumna. Camp placement, command and rules of engagement translate the diplomatic failure into military institutions.'),
      unit('Ulūkābhigamana Parva','chapters 160–164','Duryodhana sends Ulūka with deliberately insulting messages. The replies formalize old vows—especially those of Bhīma and Arjuna—and strip away the residual language of negotiation.'),
      unit('Rathātiratha-saṃkhyāna Parva','chapters 165–172','Bhīṣma and others classify warriors as rathas, atirathas and mahārathas. The rankings are strategic and polemical: Bhīṣma’s depreciation of Karṇa reactivates their rivalry and contributes to Karṇa’s refusal to fight while Bhīṣma commands.'),
      unit('Ambopākhyāna Parva','chapters 173–199','Bhīṣma tells the history of Ambā, her rejection by Śālva, conflict with Paraśurāma and rebirth as Śikhaṇḍin. A wrong produced by Bhīṣma’s earlier bride-abduction returns as the condition of his fall, binding war strategy to unresolved gendered injury.')
    ],
    interpretation:[theme('The ethics of failed diplomacy','The book records multiple chances to avoid war and distinguishes peace language from a just settlement. Dhr̥tarāṣṭra often desires safety without restoring what was taken; Kr̥ṣṇa’s mission makes that evasion public.'),theme('Knowledge without action','Vidura, Sanatsujāta, Bhīṣma and Kr̥ṣṇa give the court ample counsel. The tragedy lies not in ignorance alone but in a political order where correct diagnosis repeatedly fails to govern attachment, fear and succession.')],
    reception:['The Viduranīti and Sanatsujātīya acquired lives as independent wisdom texts, while Kr̥ṣṇa’s embassy is a central dramatic episode. Modern political readings frequently use Udyoga to ask when compromise becomes complicity and when force can be called a last resort.']
  });

  make('bhishma-parva',{
    number:6,title:'Bhīṣma Parva',devanagari:'भीष्मपर्व',meaning:'Book of Bhīṣma',traditional:'4 named divisions and 124 chapters',critical:'117 chapters',wiki:'https://en.wikipedia.org/wiki/Bhishma_Parva',
    lead:['The Bhīṣma Parva opens the Kurukṣetra war and carries it through its first ten days. Sañjaya’s divinely enabled report places the battle inside Dhr̥tarāṣṭra’s anxious listening; catalogues of the earth and its peoples magnify a dynastic conflict into a war over the known world.','Before the first charge, Arjuna refuses to kill teachers and kin. The Bhagavad Gītā answers through layered teachings on action, knowledge, disciplined practice, devotion and Kr̥ṣṇa’s cosmic form; the surrounding war then tests rather than simply illustrates those teachings.'],
    structure:['Traditional sub-parva labels and chapter boundaries vary in printed tables, especially around the Bhagavad Gītā. The narrative map below therefore uses stable event blocks and states traditional chapter ranges without pretending that every recension begins the Gītā at the same number.'],
    units:[
      unit('Jambū-khaṇḍa-vinirmāṇa','chapters 1–10','Vyāsa offers Dhr̥tarāṣṭra sight of the war; the king refuses, and Sañjaya receives supernatural vision. Omens, army arrangements and the opening question frame everything as reported knowledge shaped for a blind ruler who helped create the crisis.'),
      unit('Bhūmi Parva','chapters 11–12','Sañjaya describes continents, mountains, rivers, peoples and cosmic measures. This geography is not a modern map: it locates Kurukṣetra within epic cosmology and represents the scale of the human world now concentrated in battle.'),
      unit('Bhagavad Gītā Parva','approximately chapters 13–42; Gītā commonly 23–40','Arjuna surveys both armies, drops his bow and argues that victory cannot justify the destruction of kinship and social order. Kr̥ṣṇa distinguishes embodied self from imperishable ātman, requires action without possessive attachment, teaches multiple yogas and reveals a world-encompassing form that already contains the warriors’ deaths. Arjuna resumes his role, but the dialogue leaves readers to interpret how metaphysics, devotion and situational duty relate.'),
      unit('War days 1–5','approximately chapters 43–70','Bhīṣma’s command produces immense Pāṇḍava losses. Individual duels, shifting formations and Abhimanyu’s early prowess fill Sañjaya’s report; Kr̥ṣṇa’s anger at Arjuna’s restraint nearly makes him break his vow not to fight, while Bhīṣma welcomes death at his hands.'),
      unit('War days 6–9','approximately chapters 71–108','Violence intensifies and the Pāṇḍavas fail to dislodge Bhīṣma. After the ninth day they ask him how he can be defeated; Bhīṣma tells them he will not fight Śikhaṇḍin, whom he regards through Ambā’s former identity.'),
      unit('Bhīṣma-vadha','approximately chapters 109–124','On the tenth day Śikhaṇḍin stands before Arjuna, who pierces Bhīṣma until he falls without touching the ground. Bhīṣma chooses to remain alive on the bed of arrows until the sun’s northward course, suspending the oldest Kuru between warrior death and the later instruction of Books 12–13.')
    ],
    interpretation:[theme('The Gītā in its epic frame','The Bhagavad Gītā is both a major theological work and a scene inside a specific succession war. Reading it only as abstract spirituality loses Arjuna’s concrete objections; reading it only as propaganda for battle ignores its competing vocabularies of action, renunciation, knowledge and devotion.'),theme('Witness, blindness and narration','Dhr̥tarāṣṭra does not see the war directly. Sañjaya’s report, enabled by Vyāsa, makes knowledge immediate yet politically belated: the king can hear every consequence but cannot undo the choices that produced it.'),theme('Bhīṣma’s agency','Bhīṣma is nearly invincible but also controls the conditions and timing of his fall. His vulnerability to Śikhaṇḍin returns Ambā’s history to the centre of martial strategy and complicates any clean distinction between heroic vow and accumulated harm.')],
    reception:['The Bhagavad Gītā generated extensive Vedānta commentary, devotional exegesis, political interpretation and independent liturgical study. Its extraordinary reception should not erase the rest of Bhīṣma Parva, especially the narrative work that frames who speaks, why Arjuna hesitates and how Bhīṣma falls.']
  });

  make('drona-parva',{
    number:7,title:'Droṇa Parva',devanagari:'द्रोणपर्व',meaning:'Book of Droṇa',traditional:'8 upa-parvas and 204 chapters',critical:'8 upa-parvas and 173 chapters',wiki:'https://en.wikipedia.org/wiki/Drona_Parva',
    lead:['The Droṇa Parva covers war days eleven through fifteen under Droṇa’s command. Duryodhana asks him to capture Yudhiṣṭhira alive, so repeated attempts to draw Arjuna away reshape the battle and culminate in Abhimanyu’s isolation inside the cakravyūha.','After Abhimanyu’s death, vows drive the sequence: Arjuna must kill Jayadratha before sunset; the battle continues into night; Karṇa spends Indra’s spear on Ghaṭotkaca; and Droṇa is finally disarmed through the deliberately ambiguous report that “Aśvatthāman is dead.”'],
    units:[
      unit('Droṇābhiṣeka Parva','chapters 1–16','Karṇa reconciles with the fallen Bhīṣma and joins the battle; Droṇa is consecrated commander. He promises to seize Yudhiṣṭhira if Arjuna can be removed, making capture rather than slaughter the strategic centre of the eleventh day.'),
      unit('Saṃśaptaka-vadha Parva','chapters 17–32','Warriors sworn to conquer or die challenge Arjuna and draw him away from Yudhiṣṭhira. Their repeated suicidal attacks display the use of vows as military technology and open space for Droṇa’s more complex formations.'),
      unit('Abhimanyu-vadha Parva','chapters 33–71','Abhimanyu knows how to enter the cakravyūha but not how to leave it; the other Pāṇḍavas are blocked by Jayadratha. Surrounded after his weapons and chariot are destroyed, he is killed by multiple warriors. The breach of single-combat norms becomes the emotional and ethical pivot of the war.'),
      unit('Pratijñā Parva','chapters 72–84','Arjuna vows to kill Jayadratha by the next sunset or enter fire. Both armies reorganize around the deadline, turning a father’s grief into an inflexible public promise whose failure would destroy a principal Pāṇḍava fighter.'),
      unit('Jayadratha-vadha Parva','chapters 85–152','Arjuna cuts through layered formations while Bhūriśravas and Sātyaki enact another contested killing. Kr̥ṣṇa uses the appearance of sunset to expose Jayadratha; Arjuna kills him and sends the head to his father, fulfilling the vow through precise knowledge of an older curse.'),
      unit('Ghaṭotkaca-vadha Parva','chapters 153–184','The fighting continues after dark, when rākṣasa powers make Ghaṭotkaca devastating. To save the Kaurava army, Karṇa uses the one irresistible spear reserved for Arjuna. Kr̥ṣṇa celebrates the strategic exchange even as Bhīma loses his son, one of the epic’s starkest collisions of grief and calculation.'),
      unit('Droṇa-vadha Parva','chapters 185–193','Droṇa’s weapons overwhelm the Pāñcālas. At Kr̥ṣṇa’s urging Bhīma kills an elephant named Aśvatthāman, and Yudhiṣṭhira speaks the half-truth that breaks Droṇa’s will; Dhr̥ṣṭadyumna kills the meditating teacher, fulfilling the purpose of his birth.'),
      unit('Nārāyaṇāstra-mokṣaṇa Parva','chapters 194–204','Enraged by his father’s death, Aśvatthāman releases the Nārāyaṇāstra. Kr̥ṣṇa orders everyone to lay down weapons because the missile attacks resistance; Bhīma must be forced to submit. The paradoxical defence closes the book by opposing martial pride with tactical non-resistance.')
    ],
    interpretation:[theme('Escalation and the collapse of rules','Collective killing, night battle, deceptive speech and attacks on disarmed opponents accumulate in this book. The narrative distributes violations across both coalitions and repeatedly ties each new breach to an earlier injury.'),theme('Vows as engines of violence','The saṃśaptakas, Arjuna’s sunset vow and Dhr̥ṣṭadyumna’s birth-purpose convert personal identity into compulsory action. Vows produce courage and predictability, but also narrow the space for judgment.')],
    reception:['Abhimanyu’s death is a major emblem of youth, encirclement and unfair warfare in modern South Asian memory. The half-truth used against Droṇa has likewise become a standard case in debates over consequentialism and the corrosion of Yudhiṣṭhira’s truthfulness.']
  });

  make('karna-parva',{
    number:8,title:'Karṇa Parva',devanagari:'कर्णपर्व',meaning:'Book of Karṇa',traditional:'2 upa-parvas and 96 chapters',critical:'69 chapters',wiki:'https://en.wikipedia.org/wiki/Karna_Parva',
    lead:['The Karṇa Parva covers the sixteenth and seventeenth days, when Karṇa finally commands the Kaurava army. Its battlefield narrows toward the confrontation forecast since the tournament in Book 1, while Bhīma fulfils his oath against Duḥśāsana and the surviving forces abandon earlier limits.','Śalya drives Karṇa’s chariot and undermines him through a long exchange of insults and regional stereotypes. When Karṇa’s wheel sinks and remembered curses converge, Kr̥ṣṇa urges Arjuna to answer not an isolated appeal to fair combat but the accumulated wrongs in which Karṇa participated.'],
    units:[
      unit('Karṇa Parva','chapters 1–56','Karṇa is installed as commander and leads renewed assaults. The day includes fierce combat by Aśvatthāman, Bhīma and the Pāṇḍava allies; Bhīma kills Duḥśāsana and enacts his terrifying vow, while Karṇa spares some Pāṇḍavas in accordance with his promise to Kuntī. Śalya’s charioteering begins as a sustained psychological contest.'),
      unit('Karṇa-vadha Parva','chapters 57–96','The seventeenth day culminates in the Arjuna–Karṇa duel. Weapons counter weapons until Karṇa’s chariot wheel sinks and his knowledge fails under earlier curses. He appeals to combat law, Kr̥ṣṇa recites his role in Draupadī’s humiliation and Abhimanyu’s death, and Arjuna kills him; only later will the Pāṇḍavas learn he was their elder brother.')
    ],
    interpretation:[theme('Karna between generosity and allegiance','Karṇa’s loyalty to Duryodhana is socially and emotionally intelligible, yet it also binds him to the dice-hall abuse and the killing of Abhimanyu. The book’s tragedy depends on holding admirable generosity, humiliating exclusion, pride and culpable allegiance together.'),theme('Justice across time','The final duel disputes whether a present rule can be invoked without accounting for earlier violations. Kr̥ṣṇa’s answer is retrospective and consequential; the text makes the killing legible without making it morally clean.')],
    reception:['Karṇa became one of the epic’s most powerful modern counter-heroes, especially in works concerned with caste, merit and social exclusion. Many retellings soften his dice-hall speech or heighten his victimhood; comparison with the Sanskrit book is therefore essential.']
  });

  make('shalya-parva',{
    number:9,title:'Śalya Parva',devanagari:'शल्यपर्व',meaning:'Book of Śalya',traditional:'4 upa-parvas and 65 chapters',critical:'4 upa-parvas and 64 chapters',wiki:'https://en.wikipedia.org/wiki/Shalya_Parva',
    lead:['The Śalya Parva narrates the eighteenth and final day of organized war. Śalya becomes the fourth Kaurava commander and is killed by Yudhiṣṭhira; Sahadeva kills Śakuni, the remaining armies collapse, and Duryodhana withdraws into a lake.','Its long Gadāyuddha section interweaves Balarāma’s pilgrimage with the final mace duel. Bhīma’s prohibited strike to Duryodhana’s thigh wins the contest and fulfils an old vow, but Balarāma’s outrage and Duryodhana’s dying accusation prevent victory from becoming a simple vindication.'],
    units:[
      unit('Śalya-vadha Parva','chapters 1–22','Śalya takes command and mounts a final, aggressive formation. Yudhiṣṭhira—usually protected rather than foregrounded as a duellist—kills him with a spear, while the remnant Kaurava army loses its last formal commander.'),
      unit('Śalya Parva','chapters 23–27','Sahadeva kills Ulūka and then Śakuni, explicitly fulfilling the vow created by the dice game. The death of the gambler closes one causal line of the war, but cannot restore those already lost.'),
      unit('Hrada-praveśa Parva','chapters 28–29','Duryodhana hides within a lake and is discovered through hunters and provocation. Yudhiṣṭhira offers him a single combat and even the choice of opponent, a rash concession Kr̥ṣṇa criticizes because Duryodhana remains formidable with the mace.'),
      unit('Gadāyuddha Parva','chapters 30–65','Balarāma returns from a pilgrimage whose tīrtha stories interrupt and contextualize the duel. Duryodhana outperforms Bhīma technically until Kr̥ṣṇa signals the vulnerable thigh; Bhīma strikes below the permitted zone. The dispute among Balarāma, Kr̥ṣṇa, the Pāṇḍavas and dying Duryodhana turns the war’s last victory into an argument over vow, rule and necessity.')
    ],
    interpretation:[theme('The end of conventional war','By the last day the vast armies have contracted to named survivors and private vows. Command, kinship revenge and technical combat rules remain, but each institution is exhausted or breached.'),theme('Pilgrimage beside battle','Balarāma’s tīrtha circuit preserves an alternative sacred geography while the central field is destroyed. His return as teacher and judge also makes the duel answerable to a martial tradition larger than Kr̥ṣṇa’s strategy.')],
    reception:['The mace duel is a favourite subject of painting, theatre and television, often staged as the war’s climax. Interpretations divide over whether the thigh strike is justified retaliation, tactical necessity or a final proof that victory has consumed dharma.']
  });

  make('sauptika-parva',{
    number:10,title:'Sauptika Parva',devanagari:'सौप्तिकपर्व',meaning:'Book of the Sleeping Warriors',traditional:'2 upa-parvas and 18 chapters',critical:'2 upa-parvas and 18 chapters',wiki:'https://en.wikipedia.org/wiki/Sauptika_Parva',
    lead:['The Sauptika Parva destroys the distinction between battlefield and camp after the formal war has ended. Aśvatthāman reads an owl’s slaughter of sleeping crows as a tactical model, invokes Śiva and enters the Pāṇḍava encampment at night while Kr̥pa and Kr̥tavarman kill those who escape.','Dhr̥ṣṭadyumna, Śikhaṇḍin and Draupadī’s sons die, but the five brothers, Kr̥ṣṇa and Sātyaki are absent. The pursuit of Aśvatthāman then escalates to rival brahmaśiras weapons and an attack upon Uttara’s womb, making the unborn Parīkṣit the last target of Kuru vengeance.'],
    units:[
      unit('Sauptika Parva','chapters 1–9','Kr̥pa argues that destiny and effort work together and urges counsel before action, but Aśvatthāman equates revenge with release. After Śiva grants him force, he kills Dhr̥ṣṭadyumna without a warrior’s death and massacres the sleeping camp; Kr̥pa and Kr̥tavarman guard the exits and burn the tents.'),
      unit('Aiṣīka Parva','chapters 10–18','Draupadī demands Aśvatthāman’s defeat and the jewel from his head. Cornered near Vyāsa, he releases the brahmaśiras; Arjuna counters, but sages stop the collision. Arjuna withdraws his weapon, Aśvatthāman cannot, and redirects it toward the Pāṇḍava pregnancy; Kr̥ṣṇa preserves Parīkṣit and condemns Aśvatthāman to a wandering life.')
    ],
    interpretation:[theme('After-war violence','The night raid denies sleep, surrender and the end of hostilities any protection. Its victims include the killers of Droṇa and Bhīṣma, but retaliatory symmetry is precisely what perpetuates annihilation.'),theme('Weapons beyond human control','The brahmaśiras episode distinguishes knowing how to release power from possessing the discipline to recall it. Aśvatthāman’s failure makes the future itself—the womb and dynastic survivor—the battlefield.')],
    reception:['The owl image and the curse of Aśvatthāman have remained powerful symbols of clandestine war and unending guilt. Regional tradition often presents Aśvatthāman as an immortal still wandering, an afterlife of the Sanskrit book’s condemnation.']
  });

  make('stri-parva',{
    number:11,title:'Strī Parva',devanagari:'स्त्रीपर्व',meaning:'Book of the Women',traditional:'2 principal upa-parvas and 27 chapters',critical:'27 chapters',wiki:'https://en.wikipedia.org/wiki/Stri_Parva',
    lead:['The Strī Parva replaces battle narration with the voices and bodies of survivors. Dhr̥tarāṣṭra, Gāndhārī, Kuntī, Draupadī and the women of the slain enter the field, confront corpses and perform the first work of mourning.','Gāndhārī’s vision names warriors whom the battle books treated as combatants and returns them to mothers, wives and children. Her curse upon Kr̥ṣṇa carries the logic of Kuru destruction into the Yādava future, while Kuntī’s disclosure that Karṇa was her firstborn transforms Pāṇḍava victory into fratricide recognized too late.'],
    units:[
      unit('Jalapradānika Parva','chapters 1–15','Vidura and Vyāsa counsel the grieving Dhr̥tarāṣṭra before he meets the victors. Kr̥ṣṇa substitutes an iron image when the blind king tries to crush Bhīma; Gāndhārī questions the war’s unjust acts and Yudhiṣṭhira accepts blame. The royal households then proceed toward the dead and the water offerings.'),
      unit('Strī-vilāpa Parva','chapters 16–27','Empowered with divine sight, Gāndhārī surveys the field and laments son after son, ally after enemy. She holds Kr̥ṣṇa capable of preventing the war and curses the Yādavas to a similar end. Funeral rites follow, and Kuntī reveals Karṇa’s maternity; Yudhiṣṭhira’s grief deepens because the enemy he killed was the eldest Pāṇḍava.')
    ],
    interpretation:[theme('Lament as historical correction','The women’s laments reclassify heroic deaths as household devastation. This is not a sentimental appendix to war: it is the epic’s immediate reckoning with the categories—glory, victory, enemy—used by the battle books.'),theme('Responsibility after catastrophe','No single agent absorbs all blame. Dhr̥tarāṣṭra’s indulgence, Duryodhana’s choices, Pāṇḍava violations, Kr̥ṣṇa’s strategy and the elders’ silence are remembered together, making grief an arena of moral accusation.')],
    reception:['Gāndhārī’s curse and Kuntī’s revelation are central to modern novels and women-centred retellings. The parva has become a major source for readings that shift epic history from victorious kings toward bereaved witnesses.']
  });

  make('shanti-parva',{
    number:12,title:'Śānti Parva',devanagari:'शान्तिपर्व',meaning:'Book of Peace',traditional:'3 upa-parvas and 365 chapters',critical:'3 upa-parvas and 353 chapters',wiki:'https://en.wikipedia.org/wiki/Shanti_Parva',
    lead:['The Śānti Parva is the Mahābhārata’s longest book and its great postwar archive of political and soteriological argument. Yudhiṣṭhira wishes to renounce a throne purchased through kin-slaughter; Kr̥ṣṇa and the sages take him to Bhīṣma, still alive on the bed of arrows.','Bhīṣma’s answers range across kingship, punishment, taxation, appointment, emergency ethics, gifts, truth, non-injury, renunciation, Sāṃkhya, Yoga and liberation. The book does not offer a single code: it gathers competing models in narrative dialogues whose speakers, emergencies and audiences matter.'],
    history:['Śānti’s scale and doctrinal diversity have made its growth a major scholarly problem. Royal-dharma, emergency-dharma and mokṣa collections contain internal strata and parallels with Dharmaśāstra, Arthaśāstra, Upaniṣadic and renunciant traditions; “late” cannot be assigned mechanically to the whole.'],
    units:[
      unit('Rājadharmānuśāsana Parva','chapters 1–130','Yudhiṣṭhira’s grief, the new revelation about Karṇa and arguments against immediate renunciation lead to Bhīṣma. His royal instruction treats the origin of kingship, daṇḍa, ministers, spies, forts, treasury, war, justice and the ruler’s obligation to protect. Stories such as Śaṅkha and Likhita test whether law can bind even those close to authority.'),
      unit('Āpaddharmānuśāsana Parva','chapters 131–173','Questions shift to conduct in āpad, conditions where ordinary livelihood and rules cannot be maintained. The text permits adaptations yet worries that exception will become appetite; stories examine theft under hunger, compromised rulers, unequal bargains and the restoration of normal norms after crisis.'),
      unit('Mokṣadharma Parva','chapters 174–365','The vast final division moves through ātman, rebirth, guṇas, Sāṃkhya analysis, Yoga, renunciation, devotion and paths to liberation. Dialogues include Bhṛgu and Bharadvāja on social differentiation, Sulabhā’s philosophical encounter with Janaka, Nārāyaṇīya theology and the Nara–Nārāyaṇa tradition. Its plural voices resist reduction to one systematic school.')
    ],
    interpretation:[theme('Government after illegitimate violence','Rājadharma is delivered to a victor who doubts his right to rule. Governance is therefore not abstract statecraft: it is an attempt to make protection, justice and welfare possible after the ruling house has nearly destroyed itself.'),theme('Normal rule and emergency','Āpaddharma acknowledges that famine, defeat and mortal danger alter what agents can do. The ethical problem is temporal and institutional—who identifies emergency, how far exception extends and how ordinary accountability returns.'),theme('Plural routes to liberation','Mokṣadharma preserves household, ascetic, philosophical and devotional claims without harmonizing all differences. Its form as successive answers is essential evidence for the Mahābhārata’s encyclopaedic method.')],
    reception:['Śānti is foundational for the study of ancient Indian political thought and liberation traditions, though it has often been mined for isolated maxims. James L. Fitzgerald’s critical-edition translation and studies insist on reading its teachings in the postwar narrative and redactional setting.'],
    sources:[{title:'James L. Fitzgerald, The Mahābhārata, Book 12: The Book of Peace',detail:'Critical-edition translation and introduction (University of Chicago Press, vol. 1, 2004; vol. 2, 2026).'}]
  });

  make('anushasana-parva',{
    number:13,title:'Anuśāsana Parva',devanagari:'अनुशासनपर्व',meaning:'Book of Instructions',traditional:'2 upa-parvas and 168 chapters',critical:'2 upa-parvas and 154 chapters',wiki:'https://en.wikipedia.org/wiki/Anushasana_Parva',
    lead:['The Anuśāsana Parva continues Yudhiṣṭhira’s questioning of Bhīṣma, but shifts emphasis toward gifts, vows, food, non-injury, social and household obligations, pilgrimage, divine praise and the religious economies that bind rulers to recipients.','Its most famous units include teachings on ahiṃsā, the Viṣṇusahasranāma and narratives of Śiva and Umā. The final movement ends Bhīṣma’s suspended life: he dismisses the gathered kings, dies at the chosen solar moment and is mourned by his mother Gaṅgā.'],
    history:['The absence or different grouping of Anuśāsana in some early parva lists, including the damaged Spitzer manuscript, has generated debate about its formation. That evidence supports growth of the epic but does not by itself prove that every present chapter was added together or at one late moment.'],
    units:[
      unit('Dāna-dharma Parva','chapters 1–152','Bhīṣma answers questions about effort and destiny, marriage, guests, food, gifts, cows, ancestor rites, tīrthas and conduct toward living beings. Long story clusters authorize different recipients and gifts, while chapters on compassion and non-injury sit beside sacrificial and social prescriptions. The Viṣṇusahasranāma places a thousand-name hymn in Bhīṣma’s final instruction, and Śaiva narratives give the book a deliberately broad sectarian field.'),
      unit('Bhīṣma-svargārohaṇa Parva','chapters 153–168','With the sun moving north, Bhīṣma gives final counsel and withdraws his life-breaths. The Pāṇḍavas cremate him and offer water; Gaṅgā rises to lament, and Kr̥ṣṇa consoles her by recalling Bhīṣma’s divine Vasu identity. Instruction ends in embodied death and funeral obligation.')
    ],
    interpretation:[theme('Gift, merit and social order','Dāna is not presented as private generosity alone. It redistributes royal wealth, constructs relations among householders, rulers and brahmans, and makes recipient, intention, substance and time part of moral value.'),theme('Non-injury inside a sacrificial archive','Strong ahiṃsā formulations coexist with materials that assume sacrifice and meat. The juxtaposition is evidence of debate and textual layering; selecting one slogan as the uncontested doctrine of the whole book suppresses that history.'),theme('Sectarian plurality','Viṣṇu and Śiva receive major praise without turning the book into a simple manifesto of one exclusive community. Epic theology frequently uses identification, hierarchy and devotion in overlapping rather than mutually exclusive ways.')],
    reception:['The Viṣṇusahasranāma became an independently recited devotional text with extensive commentary. Dāna and ahiṃsā passages also entered later legal, ritual and ethical argument, often detached from Bhīṣma’s postwar audience.']
  });

  make('ashvamedhika-parva',{
    number:14,title:'Āśvamedhika Parva',devanagari:'आश्वमेधिकपर्व',meaning:'Book of the Horse Sacrifice',traditional:'2 upa-parvas and 96 chapters',critical:'one major book in 92 chapters',wiki:'https://en.wikipedia.org/wiki/Ashvamedhika_Parva',
    lead:['The Āśvamedhika Parva turns postwar sovereignty into ritual and geography. Yudhiṣṭhira must replenish the ruined treasury before performing the horse sacrifice; Arjuna follows the wandering horse, confronting kingdoms whose rulers are often descendants of men killed at Kurukṣetra.','The book also contains the Anugītā, where Arjuna asks Kr̥ṣṇa to repeat the battlefield teaching and is told that the earlier inspired state cannot simply be reproduced. The final golden-mongoose story relativizes royal splendour by comparing it with a starving family’s total gift of barley.'],
    units:[
      unit('Aśvamedhika Parva','chapters 1–15 in one traditional division; sacrifice narrative resumes later','Vyāsa directs Yudhiṣṭhira to recover Marutta’s abandoned gold, making material reconstruction a precondition of ritual sovereignty. The horse is released under Arjuna’s guard; campaigns in Trigarta, Pragjyotiṣa, Sindhu, Maṇipura and elsewhere negotiate submission with the war’s next generation. Babhruvāhana defeats and appears to kill Arjuna before Ulūpī revives him, resolving an older divine penalty.'),
      unit('Anugītā and concluding sacrifice','traditionally chapters 16–96','Kr̥ṣṇa answers Arjuna through older dialogues—the Brahman’s instruction, the dialogue of husband and wife, teacher and pupil—on mind, guṇas, action and release. After Kr̥ṣṇa returns to Dvārakā, the horse’s circuit and sacrifice are completed. A half-golden mongoose declares the costly rite inferior to a famine-stricken family’s self-emptying hospitality, leaving imperial ritual under ethical critique.')
    ],
    interpretation:[theme('Reconstruction and imperial ritual','The aśvamedha proclaims sovereignty, but its need for hidden gold and renewed campaigns shows the economic and military burden of restoration. Many encounters are with heirs, so the rite extends the war’s settlement across generations.'),theme('Why the Gītā cannot simply be repeated','Kr̥ṣṇa distinguishes the Anugītā from the earlier discourse’s extraordinary yogic context. The later teaching is more scholastic and dialogical, making memory failure a reflection on revelation, textual repetition and changed circumstances.'),theme('The mongoose’s critique','The concluding fable does not merely reject ritual. It compares value by sacrifice relative to capacity: a handful of food given under starvation can exceed royal abundance that leaves the giver secure.')],
    reception:['The Anugītā has circulated independently and attracted comparison with the Bhagavad Gītā, while the mongoose story became a classic critique of quantitative merit. Manuscripts differ in the names and internal division of the Anugītā materials, an important warning against treating one printed table as universal.']
  });

  make('ashramavasika-parva',{
    number:15,title:'Āśramavāsika Parva',devanagari:'आश्रमवासिकपर्व',meaning:'Book of Life in the Hermitage',traditional:'3 upa-parvas and 39 chapters',critical:'3 upa-parvas and 47 chapters',wiki:'https://en.wikipedia.org/wiki/Ashramavasika_Parva',
    lead:['The Āśramavāsika Parva moves the old Kuru generation from dependent residence at Yudhiṣṭhira’s court to forest renunciation. Fifteen years of apparent reconciliation cannot erase Bhīma’s hostility or Dhr̥tarāṣṭra’s grief, and the elders depart only after performing rites for the war dead.','In the forest Vidura’s energy enters Yudhiṣṭhira, and Vyāsa grants the survivors one night in which the slain rise from the river and meet their families. The reconciliation is temporary; Dhr̥tarāṣṭra, Gāndhārī and Kuntī later accept death in a forest fire, while Sañjaya escapes to the Himalaya.'],
    units:[
      unit('Āśramavāsa Parva','chapters 1–28','Yudhiṣṭhira honours Dhr̥tarāṣṭra and Gāndhārī, but Bhīma’s reminders of victory reopen pain. The old king secures wealth for śrāddha and leaves with Gāndhārī, Kuntī, Vidura and Sañjaya. When the Pāṇḍavas visit, Yudhiṣṭhira finds the emaciated Vidura; their shared identity with Dharma is marked as Vidura’s life-force enters the king.'),
      unit('Putradarśana Parva','chapters 29–36','At the request of the bereaved, Vyāsa summons the dead from the Gaṅgā for one night. Warriors appear free of anger and wounds, speak with relatives, and return at dawn; some wives follow them into the river. The vision offers reunion without undoing death or restoring the dynasty.'),
      unit('Nāradāgamana Parva','chapters 37–39','Nārada reports that the three elders refused to flee an approaching forest fire and died in yogic composure; Sañjaya was ordered away. Yudhiṣṭhira performs their rites and grieves again, showing that even visionary reconciliation does not abolish funeral duty.')
    ],
    interpretation:[theme('Renunciation after rule','Forest retirement is both a life-stage ideal and a response to unbearable dynastic memory. The elders remain bound to food, gifts, rites and attendants, so renunciation is depicted as a transition rather than instantaneous social disappearance.'),theme('Seeing the dead','Vyāsa’s nocturnal restoration changes grief through encounter, not historical reversal. The episode acknowledges the survivors’ desire for bodily recognition while keeping the dead within a cosmic order.')],
    reception:['The departure of Kuntī with Dhr̥tarāṣṭra and Gāndhārī is a major focus of modern reflection on shared grief and responsibility. The one-night resurrection has inspired visual and theatrical treatments that emphasize reconciliation beyond battle factions.']
  });

  make('mausala-parva',{
    number:16,title:'Mausala Parva',devanagari:'मौसलपर्व',meaning:'Book of the Clubs',traditional:'9 chapters without secondary upa-parvas',critical:'8 chapters',wiki:'https://en.wikipedia.org/wiki/Mausala_Parva',
    lead:['The Mausala Parva fulfils Gāndhārī’s curse thirty-six years after Kurukṣetra. A prank against visiting sages produces a cursed iron club; although pulverized, its fragments return as fatal weapons when the Yādavas quarrel at Prabhāsa.','Sātyaki and Kr̥tavarman revive accusations from the war until intoxicated violence destroys the clan. Balarāma and Kr̥ṣṇa depart, Dvārakā is submerged, and Arjuna discovers that Gāṇḍīva and the celestial weapons no longer answer him while he escorts the survivors.'],
    units:[
      unit('The curse and the iron club','chapters 1–2','Sāmba is disguised as a pregnant woman and the Yādava youths ask sages what “she” will bear. The curse produces an iron pestle destined to destroy the clan; grinding and casting it into the sea cannot defeat the prophecy, because the powder becomes eraka grass and one fragment becomes a hunter’s arrowhead.'),
      unit('Omens and the journey to Prabhāsa','chapters 3–4','Weapons and divine emblems disappear, social restraints fail and terrifying omens fill Dvārakā. Kr̥ṣṇa leads the Yādavas to the seashore pilgrimage, where the prohibition on liquor collapses and old war grievances return.'),
      unit('The Yādava fratricide','approximately chapters 4–5','Sātyaki condemns Kr̥tavarman for the night massacre; Kr̥tavarman answers with Sātyaki’s killing of Bhūriśravas. Sātyaki kills him, Pradyumna joins the fight, and eraka stalks harden into iron clubs. Kr̥ṣṇa participates in the destruction once his son and allies are slain.'),
      unit('Departures of Balarāma and Kr̥ṣṇa','approximately chapters 5–6','Balarāma releases his life in yogic withdrawal, associated with the emergence of the great serpent. The hunter Jarā mistakes Kr̥ṣṇa’s foot for an animal and shoots; Kr̥ṣṇa consoles him and ascends, turning the remnant iron fragment into the instrument of divine departure.'),
      unit('Arjuna, the survivors and submerged Dvārakā','chapters 7–9 in the vulgate','Arjuna performs rites, escorts women and children, and watches the sea cover Dvārakā. Bandits attack the caravan; his weapons fail and many captives are lost. Vyāsa explains that the age and the heroes’ appointed work have ended, leading Arjuna toward renunciation.')
    ],
    interpretation:[theme('Kurukṣetra returns inside the victors’ clan','The fatal argument explicitly reopens Bhūriśravas and the sleeping-camp massacre. Violence does not remain confined to defeated Kurus; unresolved judgments travel with the Yādava allies and erupt when political restraint disappears.'),theme('The end of heroic power','Arjuna’s failure is not ordinary ageing alone. Cosmic weapons were situational gifts, and their withdrawal marks the closure of the epic’s heroic age and Kr̥ṣṇa’s earthly presence.')],
    reception:['The submergence of Dvārakā has generated devotional geography, archaeological speculation and modern historical claims. The text should not be converted directly into a datable marine report; literary memory, sacred place and archaeology require independent methods.']
  });

  make('mahaprasthanika-parva',{
    number:17,title:'Mahāprasthānika Parva',devanagari:'महाप्रस्थानिकपर्व',meaning:'Book of the Great Departure',traditional:'3 chapters without upa-parvas',critical:'3 chapters and about 100 ślokas',wiki:'https://en.wikipedia.org/wiki/Mahaprasthanika_Parva',
    lead:['The Mahāprasthānika Parva condenses royal renunciation into three chapters. The Pāṇḍavas install Parīkṣit at Hastināpura and Vajra at Indraprastha, give up ornaments and travel with Draupadī around the subcontinent before turning north toward the Himalaya and Meru.','Agni asks Arjuna to return Gāṇḍīva; then Draupadī, Sahadeva, Nakula, Arjuna and Bhīma fall in sequence. Yudhiṣṭhira does not turn back, and a dog remains his only companion when Indra’s chariot arrives.'],
    units:[
      unit('Chapter 1 — succession and renunciation','chapter 1','News of the Yādavas confirms that the epic age has ended. Yudhiṣṭhira arranges succession and administration, the brothers adopt bark garments, and the populace fails to dissuade them. Renunciation begins with responsible transfer rather than abandonment of an unprovided kingdom.'),
      unit('Chapter 2 — the continental circuit','chapter 2','The travellers move east, south, west past submerged Dvārakā, and north. Agni requires the return of Gāṇḍīva and the inexhaustible quivers to Varuṇa; the weapons that founded Indraprastha at Khāṇḍava are relinquished before the final ascent.'),
      unit('Chapter 3 — the falls and the dog','chapter 3','Draupadī and four brothers fall, and Yudhiṣṭhira attributes each fall to partiality, pride in wisdom or beauty, boastfulness, or gluttony and strength. He refuses Indra’s offer when the dog is excluded, because abandoning a living dependent for his own felicity would violate the protection he has maintained to the end.')
    ],
    interpretation:[theme('Judgment on the road','Yudhiṣṭhira’s explanations are not neutral biographies; they are terse moral judgments delivered while he refuses to stop. Their severity has troubled commentators and retellers, especially the attribution of Draupadī’s fall to partiality for Arjuna.'),theme('Renunciation and care','The dog episode prevents liberation from becoming self-interested escape. Yudhiṣṭhira has left the dead whom he cannot revive but will not abandon a living creature that depends on him.')],
    reception:['The last journey is a major subject of Himalayan sacred geography and modern literature. Adaptations often expand the nearly silent perspectives of Draupadī and the falling brothers, challenging Yudhiṣṭhira’s compressed verdicts.']
  });

  make('svargarohana-parva',{
    number:18,title:'Svargārohaṇa Parva',devanagari:'स्वर्गारोहणपर्व',meaning:'Book of the Ascent to Heaven',traditional:'5 chapters without upa-parvas',critical:'5 chapters',wiki:'https://en.wikipedia.org/wiki/Svargarohana_Parva',
    lead:['The Svargārohaṇa Parva closes the Mahābhārata through a final set of reversals. The dog is revealed as Dharma, but heaven contains Duryodhana rather than the companions Yudhiṣṭhira expects; he refuses felicity without them and is led to a place of torment.','The hell-vision proves temporary—a last test and a proportionate experience of the consequences of Yudhiṣṭhira’s own deception. Once the illusion ends, the epic’s warriors appear in divine identities and old enmity dissolves, after which the recitation returns to Janamejaya’s sacrificial frame.'],
    units:[
      unit('Chapter 1 — Dharma revealed','chapter 1','Yudhiṣṭhira’s refusal to abandon the dog completes the test begun during the forest exile. Dharma reveals himself and praises the king, who enters heaven in his human body rather than through ordinary death.'),
      unit('Chapter 2 — Duryodhana in heaven','chapter 2','Yudhiṣṭhira sees Duryodhana honoured among warriors and protests the absence of his brothers, Draupadī and Karṇa. Nārada explains heroic heaven, but Yudhiṣṭhira rejects a bliss organized without those he loves.'),
      unit('Chapter 3 — the hell-vision','chapter 3','A divine messenger leads him through filth, darkness and cries of pain. Hearing the voices of his kin, Yudhiṣṭhira chooses to remain with them rather than return to heaven, making solidarity more important than personal reward.'),
      unit('Chapter 4 — the final test ends','chapter 4','The scene dissolves when the gods and Dharma appear. Yudhiṣṭhira’s experience is explained as both test and brief consequence of the half-truth that disarmed Droṇa; bathing in the celestial Gaṅgā removes human grief and anger.'),
      unit('Chapter 5 — divine identities and closure','chapter 5','The Pāṇḍavas, Draupadī, Karṇa, Kauravas and allies are shown in their divine forms and appointed realms. Vaiśaṃpāyana completes the narrative and the frame reasserts the religious merit of hearing the Bhārata, closing a poem whose moral conflicts were never cancelled by knowing the cosmic cast list.')
    ],
    interpretation:[theme('Why Duryodhana reaches heaven','Warrior heaven follows one economy of merit and does not equal a total moral acquittal. Yudhiṣṭhira’s outrage exposes the inadequacy of any afterlife scheme that appears to ignore relational injury.'),theme('Testing the righteous king','The last two books repeat Yudhiṣṭhira’s defining tests: impartiality, protection of dependants and willingness to share the condition of others. Heaven is accepted only after loyalty survives the temptation of isolated salvation.')],
    reception:['The hell-vision has been read as theological resolution, narrative provocation and critique of simplistic karmic accounting. Many abridgements omit its discomfort, but it is essential to the epic’s refusal of a merely triumphal ending.']
  });

  make('harivamsa',{
    number:'Supplement',title:'Harivaṃśa',devanagari:'हरिवंश',position:'Khila (supplement) traditionally attached to the Mahābhārata',meaning:'Genealogy of Hari',traditional:'3 parvas and about 16,000 verses in many vulgate editions',critical:'3 parvas, 118 chapters and about 6,000 ślokas',wiki:'https://en.wikipedia.org/wiki/Harivamsa',
    lead:['The Harivaṃśa is the Mahābhārata’s traditional khila or supplement, not a nineteenth parva identical in status to the eighteen-book war narrative. It extends dynastic genealogy into a sustained account of Kr̥ṣṇa’s birth, childhood at Vraja, overthrow of Kaṃsa and Yādava world.','Its manuscript tradition is highly expansive. The critical edition constituted a much shorter text than popular vulgates, placing numerous cosmological, ritual and tīrtha passages in appendices; any quotation should therefore identify edition and chapter system.'],
    history:['The work connects epic Kṛṣṇa with developing Purāṇic biography, but simple labels such as “late appendix” do not date all its layers. Genealogical, pastoral, heroic, cosmogonic and future-oriented materials have distinct comparative histories.'],
    structure:['The three-part division—Harivaṃśa, Viṣṇu and Bhaviṣya parvans—is stable at a large scale, while the contents and extent of the last division vary markedly. P. L. Vaidya’s critical edition (1969–1971) must be distinguished from longer vulgate editions.'],
    numberingNote:'The ranges below describe the three large parvans rather than one universal vulgate chapter sequence; critical and regional editions diverge substantially.',
    units:[
      unit('Harivaṃśa Parvan','genealogical opening','Creation and solar and lunar genealogies lead toward the Yādavas. The line of Hari places Kr̥ṣṇa inside the dynastic history presupposed by the Mahābhārata and supplies ancestral connections that the eighteen books mention only selectively.'),
      unit('Viṣṇu Parvan','Kr̥ṣṇa biography','Kaṃsa’s threat, the transfer of the embryo Balarāma, Kr̥ṣṇa’s birth, childhood among cowherds, combats with hostile beings, lifting Govardhana, the move to Mathurā and Kaṃsa’s death form the narrative centre. Later campaigns, marriages and Dvārakā material connect pastoral deity, Vṛṣṇi hero and Viṣṇu theology.'),
      unit('Bhaviṣya Parvan','cosmology, rites and future discourse','The final parvan contains creation and dissolution materials, royal and ritual narratives and future-oriented discourse. Its instability across witnesses is particularly high, and many familiar vulgate chapters are absent from the critically constituted text or preserved in appendices.')
    ],
    interpretation:[theme('From epic ally to complete divine biography','The Mahābhārata assumes much about Kr̥ṣṇa without narrating his childhood. The Harivaṃśa fills that narrative absence and makes genealogy, pastoral wonder and cosmic Viṣṇu identity mutually supporting.'),theme('Supplement and textual boundary','Calling the work khila marks attachment and difference simultaneously. Its history shows that the boundary of a “complete Mahābhārata” has always been a transmissional and editorial decision.')],
    reception:['The Harivaṃśa is a crucial bridge between epic and Purāṇic Kr̥ṣṇa traditions and influenced Sanskrit and vernacular biography, art and performance. Its child-Kr̥ṣṇa material should be compared, not conflated, with the Bhāgavata Purāṇa’s later and more fully devotional arrangement.'],
    textualHistory:['P. L. Vaidya edited the Harivaṃśa critical edition for BORI in two volumes (text and appendices). Its large appendix is indispensable evidence for the work’s reception and growth, even where passages were not admitted to the constituted text.'],
    sources:[{title:'P. L. Vaidya (ed.), The Harivaṃśa, Critical Edition',detail:'BORI, 1969–1971; constituted text with extensive appendices.'}]
  });

  const order=[
    ['adi-parva','Ādi Parva'],['sabha-parva','Sabhā Parva'],['vana-parva','Vana Parva'],['virata-parva','Virāṭa Parva'],['udyoga-parva','Udyoga Parva'],['bhishma-parva','Bhīṣma Parva'],['drona-parva','Droṇa Parva'],['karna-parva','Karṇa Parva'],['shalya-parva','Śalya Parva'],['sauptika-parva','Sauptika Parva'],['stri-parva','Strī Parva'],['shanti-parva','Śānti Parva'],['anushasana-parva','Anuśāsana Parva'],['ashvamedhika-parva','Āśvamedhika Parva'],['ashramavasika-parva','Āśramavāsika Parva'],['mausala-parva','Mausala Parva'],['mahaprasthanika-parva','Mahāprasthānika Parva'],['svargarohana-parva','Svargārohaṇa Parva'],['harivamsa','Harivaṃśa supplement']
  ];
  order.forEach(([slug],i)=>{
    const x=D[`mahabharata/${slug}`];
    if(i)x.previous={title:order[i-1][1],url:`${base}${order[i-1][0]}/`};
    else x.previous={title:'Mahābhārata overview',url:base};
    if(i<order.length-1)x.next={title:order[i+1][1],url:`${base}${order[i+1][0]}/`};
    else x.next={title:'Mahābhārata overview',url:base};
  });
})();
